import json
import math

def is_square(m):
    return m >= 0 and math.isqrt(m) ** 2 == m

def expr(n):
    return (n**3 + 39*n - 2) * math.factorial(n) + 17 * 21**n + 5

# Exact check for n = 0..6 (0 is included so the scan is complete; it is not a solution).
small = {n: expr(n) for n in range(0, 7)}
small_square = {n: is_square(v) for n, v in small.items()}
solutions_small = [n for n in range(1, 7) if small_square[n]]

# Modular argument for n >= 7: 7 | n!, and 7 | 21^n for n >= 1, so
# expr(n) == 5 (mod 7). Squares mod 7 are {0,1,2,4}, so 5 is not a square residue.
square_residues_mod7 = {(x * x) % 7 for x in range(7)}
residue_claim_ok = 5 not in square_residues_mod7
residues_checked = {n: expr(n) % 7 for n in range(7, 40)}
residue_all_five = all(r == 5 for r in residues_checked.values())

settled = residue_claim_ok and residue_all_five

if settled:
    if solutions_small:
        final_answer = "n = " + ", ".join(str(n) for n in solutions_small)
    else:
        final_answer = "no natural n"
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "values_n0_to_6": {str(n): str(v) for n, v in small.items()},
    "square_flags_n0_to_6": {str(n): f for n, f in small_square.items()},
    "solutions_n1_to_6": solutions_small,
    "square_residues_mod7": sorted(square_residues_mod7),
    "residue_mod7_for_n7_to_39_all_5": residue_all_five,
    "tail_argument": "n>=7: expr(n) == 5 (mod 7), 5 is a non-residue mod 7",
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}, separators=(",", ":")))
